INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111101', 'en', 'Mysuru Palace (Amba Vilas)', 'Historic seat of the Wadiyar dynasty and architectural masterpiece in the heart of Mysuru.', 'Amba Vilas Palace, commonly known as Mysore Palace, is an Indo-Saracenic royal residence designed by British architect Henry Irwin and completed in 1912. It features ornate domes, stained glass pavilions, and the magnificent Durbar Hall.', 'Located 2 km from Mysuru Railway Station. Regular KSRTC buses and auto-rickshaws connect from Mysuru Suburb Bus Stand.', 'Wheelchairs available at the north gate; ground floor is accessible via gentle ramps.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111101', 'kn', 'ಮೈಸೂರು ಅರಮನೆ (ಅಂಬಾ ವಿಲಾಸ)', 'ಒಡೆಯರ್ ರಾಜವಂಶದ ಐತಿಹಾಸಿಕ ಆಸ್ಥಾನ ಮತ್ತು ಮೈಸೂರಿನ ಹೃದಯಭಾಗದಲ್ಲಿರುವ ವಾಸ್ತುಶಿಲ್ಪದ ಅದ್ಭುತ.', 'ಮೈಸೂರು ಅರಮನೆಯು ಇಂಡೋ-ಸಾರ್ಸೆನಿಕ್ ಶೈಲಿಯ ರಾಜಭವನವಾಗಿದ್ದು, 1912 ರಲ್ಲಿ ನಿರ್ಮಾಣಗೊಂಡಿತು. ಇಲ್ಲಿನ ದರ್ಬಾರ್ ಸಭಾಂಗಣ ಮತ್ತು ಕಲ್ಯಾಣ ಮಂಟಪಗಳು ವಿಶ್ವಪ್ರಸಿದ್ಧವಾಗಿವೆ.', 'ಮೈಸೂರು ರೈಲ್ವೆ ನಿಲ್ದಾಣದಿಂದ 2 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ. ನಗರ ಸಾರಿಗೆ ಬಸ್‌ಗಳು ಮತ್ತು ಆಟೋಗಳು ಲಭ್ಯವಿದೆ.', 'ಉತ್ತರ ದ್ವಾರದಲ್ಲಿ ಗಾಲಿಕುರ್ಚಿಗಳು ಲಭ್ಯವಿವೆ; ನೆಲಮಹಡಿಗೆ ರ‍್ಯಾಂಪ್ ವ್ಯವಸ್ಥೆ ಇದೆ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
