INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111102', 'en', 'Virupaksha Temple, Hampi', '7th-century sacred temple dedicated to Lord Shiva on the banks of the Tungabhadra River.', 'Part of the Group of Monuments at Hampi UNESCO World Heritage Site. The temple has functioned uninterruptedly since its foundation in the 7th century, expanding significantly under Vijayanagara ruler Krishnadevaraya.', 'Located 13 km from Hospet Railway Station. Regular KSRTC local buses connect Hospet to Hampi Bazaar.', 'Historic stone threshold steps and uneven paving throughout courtyard.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111102', 'kn', 'ವಿರೂಪಾಕ್ಷ ದೇವಾಲಯ, ಹಂಪಿ', 'ತುಂಗಭದ್ರಾ ನದಿಯ ತೀರದಲ್ಲಿರುವ ಶಿವನಿಗೆ ಸಮರ್ಪಿತವಾದ 7ನೇ ಶತಮಾನದ ಪವಿತ್ರ ಪುಣ್ಯಕ್ಷೇತ್ರ.', 'ಯುನೆಸ್ಕೋ ವಿಶ್ವ ಪರಂಪರೆಯ ತಾಣವಾದ ಹಂಪಿಯ ಪ್ರಮುಖ ದೇವಾಲಯ. ವಿಜಯನಗರ ಸಾಮ್ರಾಜ್ಯದ ಶ್ರೀ ಕೃಷ್ಣದೇವರಾಯರ ಕಾಲದಲ್ಲಿ ವಿಸ್ತರಿಸಲ್ಪಟ್ಟಿತು.', 'ಹೊಸಪೇಟೆ ರೈಲ್ವೆ ನಿಲ್ದಾಣದಿಂದ 13 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ. ಹೊಸಪೇಟೆಯಿಂದ ನಿರಂತರ ಬಸ್ ಸಂಪರ್ಕವಿದೆ.', 'ಪ್ರಾಚೀನ ಕಲ್ಲಿನ ಮೆಟ್ಟಿಲುಗಳಿರುವುದರಿಂದ ಗಾಲಿಕುರ್ಚಿ ಸಂಚಾರ ಸವಾಲಾಗಿದೆ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
