INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111103', 'en', 'Abbey Falls, Madikeri', 'Scenic 70-foot cascade tucked within private coffee and spice plantations in Coorg.', 'Abbey Falls (also called Abbi Falls) drops into the Kaveri River basin amidst lush Western Ghats flora and spice estates. A hanging pedestrian bridge offers vantage viewpoints.', 'Located 8 km from Madikeri town center via Galibeedu Road. Taxis and autos are readily available.', 'Steep paved walking path with over 150 steps from parking area down to viewpoint.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111103', 'kn', 'ಅಬ್ಬಿ ಜಲಪಾತ, ಮಡಿಕೇರಿ', 'ಕೊಡಗಿನ ಕಾಫಿ ತೋಟಗಳ ನಡುವೆ ಧುಮ್ಮಿಕ್ಕುವ 70 ಅಡಿ ಎತ್ತರದ ನಯನಮನೋಹರ ಜಲಪಾತ.', 'ಪಶ್ಚಿಮ ಘಟ್ಟಗಳ ಹಸಿರಿನ ನಡುವೆ ಕಾವೇರಿ ನದಿ ಕಣಿವೆಯತ್ತ ಹರಿಯುವ ಸುಂದರ ಜಲಪಾತ. ತೂಗುಸೇತುವೆಯು ವೀಕ್ಷಣೆಗೆ ಉತ್ತಮ ತಾಣವಾಗಿದೆ.', 'ಮಡಿಕೇರಿ ಪಟ್ಟಣದಿಂದ ಗಾಳಿಬೀಡು ರಸ್ತೆಯ ಮೂಲಕ 8 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ.', 'ವಾಹನ ನಿಲ್ದಾಣದಿಂದ ಜಲಪಾತಕ್ಕೆ ಇಳಿಯಲು ಸುಮಾರು 150 ಮೆಟ್ಟಿಲುಗಳಿವೆ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
