INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111104', 'en', 'Mullayanagiri Peak', 'Highest peak in Karnataka at 1,930 meters above sea level in the Baba Budan Giri range.', 'Named after the sage Mullappa Swamy whose shrine sits atop the summit, Mullayanagiri offers panoramic vistas of the Western Ghats grasslands. Accessible by trek or concrete road followed by 450 steps.', '22 km from Chikkamagaluru bus station via Bababudangiri road. Private vehicles can reach base parking.', 'High wind exposure, steep steps to summit; not wheelchair accessible.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111104', 'kn', 'ಮುಳ್ಳಯ್ಯನಗಿರಿ ಶಿಖರ', 'ಬಾಬಾಬುಡನ್ ಗಿರಿ ಶ್ರೇಣಿಯಲ್ಲಿ ಸಮುದ್ರ ಮಟ್ಟದಿಂದ 1,930 ಮೀಟರ್ ಎತ್ತರದಲ್ಲಿರುವ ಕರ್ನಾಟಕದ ಅತ್ಯುನ್ನತ ಶಿಖರ.', 'ಮುಳ್ಳಪ್ಪ ಸ್ವಾಮಿಯ ಗದ್ದುಗೆ ಹೊಂದಿರುವ ಈ ಶಿಖರವು ಪಶ್ಚಿಮ ಘಟ್ಟಗಳ ಅದ್ಭುತ ದೃಶ್ಯಾವಳಿಗಳನ್ನು ಒದಗಿಸುತ್ತದೆ.', 'ಚಿಕ್ಕಮಗಳೂರಿನಿಂದ ಸುಮಾರು 22 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ. ವಾಹನ ನಿಲ್ದಾಣದವರೆಗೆ ರಸ್ತೆ ಸಂಪರ್ಕವಿದೆ.', 'ಶಿಖರದ ತುದಿಗೆ ತಲುಪಲು ಸುಮಾರು 450 ಕಡಿದಾದ ಮೆಟ್ಟಿಲುಗಳನ್ನು ಹತ್ತಬೇಕು.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
