INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111105', 'en', 'Jog Falls (Gerosoppa)', 'Second-highest plunge waterfall in India created by the Sharavathi River dropping 253 meters.', 'Formed by four distinct cascades named Raja, Roarer, Rocket, and Rani, Jog Falls is spectacular during the post-monsoon months (August to November). The tourism viewpoint complex has paved amphitheaters.', 'Located 100 km from Shivamogga city and 30 km from Sagara railway station. Regular buses connect from Sagara.', 'Viewpoint pavilions are ramp-accessible; stairway to gorge base has over 1,400 steps.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111105', 'kn', 'ಜೋಗ ಜಲಪಾತ', 'ಶರಾವತಿ ನದಿಯಿಂದ ಸೃಷ್ಟಿಯಾದ 253 ಮೀಟರ್ ಎತ್ತರದ ಭಾರತದ ಪ್ರಸಿದ್ಧ ಜಲಪಾತ.', 'ರಾಜ, ರೋರರ್, ರಾಕೆಟ್ ಮತ್ತು ರಾಣಿ ಎಂಬ ನಾಲ್ಕು ಕವಲುಗಳಾಗಿ ಧುಮ್ಮಿಕ್ಕುವ ವಿಶ್ವವಿಖ್ಯಾತ ಜಲಪಾತ. ಮುಂಗಾರಿನ ನಂತರದ ದಿನಗಳಲ್ಲಿ ಅತ್ಯಂತ ವೈಭವೋಪೇತವಾಗಿರುತ್ತದೆ.', 'ಸಾಗರದಿಂದ 30 ಕಿ.ಮೀ ಮತ್ತು ಶಿವಮೊಗ್ಗದಿಂದ 100 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ. ಸಾಗರದಿಂದ ಬಸ್ ವ್ಯವಸ್ಥೆಯಿದೆ.', 'ಮುಖ್ಯ ವೀಕ್ಷಣಾ ವೇದಿಕೆಗಳಿಗೆ ರ‍್ಯಾಂಪ್ ಸೌಲಭ್ಯವಿದೆ; ಕಣಿವೆಯ ತಳಕ್ಕೆ 1,400 ಮೆಟ್ಟಿಲುಗಳಿವೆ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
