INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111106', 'en', 'Om Beach, Gokarna', 'Naturally shaped in the sacred Hindu symbol ''Om'' along the Karavali Arabian Sea coast.', 'Om Beach features two adjoining crescent coves bordered by laterite cliffs and rocky shores. It connects to Half Moon Beach and Paradise Beach via coastal trekking paths.', 'Located 6 km from Gokarna town. Auto-rickshaws and two-wheelers ply between Gokarna and Om Beach.', 'Rocky descent from road level to beach sand. Uneven footpaths.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111106', 'kn', 'ಓಂ ಕಡಲತೀರ, ಗೋಕರ್ಣ', 'ಅರೇಬಿಯನ್ ಸಮುದ್ರ ತೀರದಲ್ಲಿ ನೈಸರ್ಗಿಕವಾಗಿ ''ಓಂ'' ಆಕಾರವನ್ನು ಹೋಲುವ ಪ್ರಸಿದ್ಧ ಕಡಲತೀರ.', 'ಗೋಕರ್ಣದ ಸುಂದರ ಕಡಲತೀರಗಳಲ್ಲಿ ಒಂದಾಗಿದ್ದು, ಬಂಡೆಗಳು ಮತ್ತು ಮರಳಿನಿಂದ ಕೂಡಿದೆ. ಇಲ್ಲಿಂದ ಹಾಫ್ ಮೂನ್ ಮತ್ತು ಪ್ಯಾರಡೈಸ್ ಬೀಚ್‌ಗೆ ಚಾರಣ ಮಾರ್ಗವಿದೆ.', 'ಗೋಕರ್ಣ ಪಟ್ಟಣದಿಂದ 6 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ. ಆಟೋ ಮತ್ತು ವಾಹನ ಸೌಕರ್ಯವಿದೆ.', 'ರಸ್ತೆಯಿಂದ ಬೀಚ್‌ಗೆ ಇಳಿಯಲು ಬಂಡೆಗಳ ಕಡಿದಾದ ಹಾದಿಯಿದೆ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
