INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111107', 'en', 'Chennakeshava Temple, Belur', '12th-century Hoysala soapstone architectural marvel commissioned by King Vishnuvardhana.', 'Part of the Sacred Ensembles of the Hoysalas UNESCO World Heritage Site. Renowned for its intricate star-shaped platform, bracket figures (Madanikas), and detailed friezes depicting epics and flora.', '38 km from Hassan city; 16 km from Halebidu. Frequent buses operate on the Hassan-Belur corridor.', 'Courtyard entry has paved pathways; temple sanctum elevated on 1-meter high star platform with steps.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111107', 'kn', 'ಚೆನ್ನಕೇಶವ ದೇವಾಲಯ, ಬೇಲೂರು', 'ಹೊಯ್ಸಳ ದೊರೆ ವಿಷ್ಣುವರ್ಧನನಿಂದ 12ನೇ ಶತಮಾನದಲ್ಲಿ ನಿರ್ಮಿಸಲ್ಪಟ್ಟ ಅದ್ಭುತ ಶಿಲ್ಪಕಲೆಯ ಬೀಡು.', 'ಯುನೆಸ್ಕೋ ವಿಶ್ವ ಪರಂಪರೆ ತಾಣ. ನಕ್ಷತ್ರಾಕಾರದ ಜಗತಿ ಮತ್ತು ಕಲ್ಲಿನಲ್ಲಿ ಕೆತ್ತಲಾದ ಶಿಲಾಬಾಲಿಕೆಯರ ಮೂರ್ತಿಗಳಿಗೆ ಜಗತ್ಪ್ರಸಿದ್ಧವಾಗಿದೆ.', 'ಹಾಸನ ನಗರದಿಂದ 38 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ. ನೇರ ಬಸ್ ಸಂಪರ್ಕವಿದೆ.', 'ದೇವಾಲಯದ ಆವರಣ ಸಮತಟ್ಟಾಗಿದೆ; ಮುಖ್ಯ ಮಂಟಪಕ್ಕೆ ಮೆಟ್ಟಿಲುಗಳಿವೆ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
