INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111108', 'en', 'Sri Krishna Matha, Udupi', '13th-century Vaishnavite monastery founded by philosopher Saint Madhvacharya.', 'Famous for the Kanakana Kindi—a nine-holed silver-plated window through which the deity Krishna is worshipped. The complex serves traditional satvik annadana (free meals) to thousands daily.', '3 km from Udupi Railway Station. Centrally situated in Udupi car street area.', 'Crowded sanctum corridor; temple dress code strictly enforced; ramp at rear entry.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111108', 'kn', 'ಶ್ರೀ ಕೃಷ್ಣ ಮಠ, ಉಡುಪಿ', '13ನೇ ಶತಮಾನದಲ್ಲಿ ಜಗದ್ಗುರು ಶ್ರೀ ಮಧ್ವಾಚಾರ್ಯರಿಂದ ಸ್ಥಾಪಿಸಲ್ಪಟ್ಟ ಪವಿತ್ರ ಕೃಷ್ಣ ದೇವಸ್ಥಾನ.', 'ಕನಕನ ಕಿಂಡಿಯ ಮೂಲಕ ಕೃಷ್ಣನ ದರ್ಶನ ಪಡೆಯುವ ವಿಶೇಷ ಸಂಪ್ರದಾಯ. ಇಲ್ಲಿ ಪ್ರತಿದಿನ ಸಾವಿರಾರು ಭಕ್ತರಿಗೆ ಅನ್ನದಾನ ನಡೆಯುತ್ತದೆ.', 'ಉಡುಪಿ ರೈಲ್ವೆ ನಿಲ್ದಾಣದಿಂದ 3 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ.', 'ಸಾಂಪ್ರದಾಯಿಕ ಉಡುಪು ಕಡ್ಡಾಯ; ಹಿಂಬದಿಯ ಪ್ರವೇಶದ್ವಾರದಲ್ಲಿ ರ‍್ಯಾಂಪ್ ಇದೆ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
