INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111109', 'en', 'Lalbagh Botanical Garden', 'Historic 240-acre botanical haven commissioned by Hyder Ali in 1760 with iconic Glass House.', 'Lalbagh houses over 1,800 species of exotic flora, century-old trees, the Kempe Gowda tower atop a 3,000-million-year-old Peninsular Gneiss rock, and a lake with walking trails.', 'Direct connectivity via Lalbagh Metro Station (Green Line). Multiple BMTC bus routes.', 'Paved wide walkways suitable for strollers and wheelchairs; electric buggy tours available.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111109', 'kn', 'ಲಾಲ್‌ಬಾಗ್ ಸಸ್ಯತೋಟ', '1760 ರಲ್ಲಿ ಹೈದರಾಲಿ ಕಾಲದಲ್ಲಿ ಪ್ರಾರಂಭವಾದ ಐತಿಹಾಸಿಕ 240 ಎಕರೆ ವಿಸ್ತೀರ್ಣದ ಸಸ್ಯಶಾಸ್ತ್ರೀಯ ಉದ್ಯಾನ.', 'ಲಂಡನ್ನಿನ ಕ್ರಿಸ್ಟಲ್ ಪ್ಯಾಲೇಸ್ ಮಾದರಿಯ ಗಾಜಿನ ಮನೆ, ಅಪರೂಪದ ಸಸ್ಯ ಪ್ರಭೇದಗಳು ಮತ್ತು ಕೆಂಪೇಗೌಡರ ಗೋಪುರವನ್ನು ಒಳಗೊಂಡಿದೆ.', 'ಲಾಲ್‌ಬಾಗ್ ಮೆಟ್ರೋ ನಿಲ್ದಾಣದ ಮೂಲಕ ನೇರ ಸಂಪರ್ಕವಿದೆ. ನಗರದ ಎಲ್ಲೆಡೆಯಿಂದ ಬಸ್ ಸೌಲಭ್ಯವಿದೆ.', 'ಸಮತಟ್ಟಾದ ಡಾಂಬರು ರಸ್ತೆಗಳು, ಗಾಲಿಕುರ್ಚಿಗಳಿಗೆ ಸೂಕ್ತವಾಗಿದೆ; ಬ್ಯಾಟರಿ ಚಾಲಿತ ವಾಹನಗಳು ಲಭ್ಯ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
