INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111110', 'en', 'Nagarahole National Park (Tiger Reserve)', 'Premier tiger and elephant sanctuary in the Nilgiri Biosphere Reserve.', 'Also known as Rajiv Gandhi National Park, Nagarahole spans 643 sq km of moist deciduous forests. Safaris are organized by the Forest Department from the Nanachi and Veeranahosahalli gates.', '85 km from Mysuru via Hunsur-Murkal road. Advance booking recommended via forest portal.', 'Safari vehicles are high-clearance jeeps/canters; requires physical climbing assistance.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111110', 'kn', 'ನಾಗರಹೊಳೆ ರಾಷ್ಟ್ರೀಯ ಉದ್ಯಾನವನ', 'ನೀಲಗಿರಿ ಜೀವಗೋಳ ಪ್ರದೇಶದಲ್ಲಿರುವ ಕರ್ನಾಟಕದ ಪ್ರಮುಖ ಹುಲಿ ಮತ್ತು ಆನೆ ಸಂರಕ್ಷಿತಾರಣ್ಯ.', 'ರಾಜೀವ್ ಗಾಂಧಿ ರಾಷ್ಟ್ರೀಯ ಉದ್ಯಾನವನ ಎಂದೂ ಕರೆಯಲ್ಪಡುವ ಈ ಅರಣ್ಯವು ಹುಲಿ, ಚಿರತೆ, ಕಾಡೆಮ್ಮೆ ಮತ್ತು ಆನೆಗಳ ಆವಾಸಸ್ಥಾನವಾಗಿದೆ.', 'ಮೈಸೂರಿನಿಂದ ಹುಣಸೂರು ಮಾರ್ಗವಾಗಿ 85 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ.', 'ಸಫಾರಿ ವಾಹನಗಳು ಎತ್ತರವಾಗಿರುವುದರಿಂದ ಗಾಲಿಕುರ್ಚಿ ನೇರ ಪ್ರವೇಶವಿಲ್ಲ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
