INSERT INTO public.destinations (id, slug, district_code, category, latitude, longitude, access_status, verification_status, content_status, is_offbeat, estimated_visit_minutes, entry_fee_min_inr, entry_fee_max_inr, currency_code, active) VALUES ('11111111-1111-4111-8111-111111111111', 'yana-rocks-caves', 'KA-UKN', 'nature'::public.destination_category, 14.5908, 74.5614, 'open_reported'::public.access_status, 'source_checked'::public.verification_status, 'published'::public.content_status, TRUE, 120, 20.0, 20.0, 'INR', TRUE) ON CONFLICT (slug) DO UPDATE SET district_code = EXCLUDED.district_code, category = EXCLUDED.category, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, access_status = EXCLUDED.access_status, verification_status = EXCLUDED.verification_status, content_status = EXCLUDED.content_status, is_offbeat = EXCLUDED.is_offbeat, estimated_visit_minutes = EXCLUDED.estimated_visit_minutes, entry_fee_min_inr = EXCLUDED.entry_fee_min_inr, entry_fee_max_inr = EXCLUDED.entry_fee_max_inr, active = EXCLUDED.active, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111111', 'en', 'Yana Rocks & Caves', 'Towering solid black crystalline karst limestone monoliths rising from dense Sahyadri rainforests.', 'The two prominent monoliths—Bhairaveshwara Shikhara (120 m) and Mohini Shikhara (90 m)—harbor a cave temple with a self-manifested linga. An editorial offbeat trek through Western Ghats biodiversity.', 'Located 28 km from Kumta and 45 km from Sirsi. A 1.5 km forest trail trek leads from vehicle parking.', 'Forest footpath with uneven natural rocks and tree roots; sturdy footwear required.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111111', 'kn', 'ಯಾಣದ ಬಂಡೆಗಳು ಮತ್ತು ಗುಹೆಗಳು', 'ಸಹ್ಯಾದ್ರಿ ಅರಣ್ಯದ ನಡುವೆ ಎದ್ದು ನಿಂತಿರುವ ಕಪ್ಪು ಸುಣ್ಣದ ಕಲ್ಲಿನ ಭೈರವೇಶ್ವರ ಮತ್ತು ಮೋಹಿನಿ ಶಿಖರಗಳು.', 'ದಟ್ಟ ಕಾಡಿನ ನಡುವಿನ ವಿಶಿಷ್ಟ ಪ್ರಾಕೃತಿಕ ವಿಸ್ಮಯ. ಇಲ್ಲಿನ ಗುಹೆಯಲ್ಲಿ ಸ್ವಯಂಭೂ ಶಿವಲಿಂಗವಿದೆ. ಪ್ರಶಾಂತ ಪರಿಸರದಲ್ಲಿ ಚಾರಣಕ್ಕೆ ಸೂಕ್ತವಾಗಿದೆ.', 'ಕುಮಟಾದಿಂದ 28 ಕಿ.ಮೀ ಮತ್ತು ಶಿರಸಿಯಿಂದ 45 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ. ಕಾಡಿನ ಹಾದಿಯಲ್ಲಿ 1.5 ಕಿ.ಮೀ ನಡೆದು ಹೋಗಬೇಕು.', 'ಕಾಡಿನ ಹಾದಿಯಲ್ಲಿ ಕಲ್ಲು-ಮಣ್ಣಿನ ಮೆಟ್ಟಿಲುಗಳಿವೆ; ಗಾಲಿಕುರ್ಚಿ ಸಂಚಾರ ಅಸಾಧ್ಯ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
