INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111112', 'en', 'Kavaledurga Fort', '9th-century hill fortress of the Keladi Nayakas nestled in dense Western Ghats foliage near Thirthahalli.', 'Originally built in the 9th century and fortified by King Venkatappa Nayaka in the 16th century, Kavaledurga features seven concentric tiers of granite defensive walls, stepped wells, and the ruined palace palace complex. Admission fees are unverified/free locally.', 'Located 18 km from Thirthahalli. Motor vehicle access until fort foothills, followed by a 2 km uphill trek.', 'Uphill hike across uneven stone steps and grass slopes; unmaintained masonry in ruined sections.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
INSERT INTO public.destination_translations (destination_id, language_code, name, summary, description, how_to_reach, accessibility_notes, translation_status) VALUES ('11111111-1111-4111-8111-111111111112', 'kn', 'ಕವಲೆದುರ್ಗ ಕೋಟೆ', 'ತೀರ್ಥಹಳ್ಳಿ ಸಮೀಪ ಪಶ್ಚಿಮ ಘಟ್ಟಗಳ ಹಸಿರಿನ ನಡುವೆ ನೆಲೆಸಿರುವ ಕೆಳದಿ ನಾಯಕರ 9ನೇ ಶತಮಾನದ ಐತಿಹಾಸಿಕ ಗಿರಿ ದುರ್ಗ.', 'ಏಳು ಸುತ್ತಿನ ಕೋಟೆ ಗೋಡೆಗಳು, ಅರಮನೆಯ ಅವಶೇಷಗಳು ಮತ್ತು ಕಲ್ಯಾಣಿಗಳನ್ನು ಹೊಂದಿರುವ ಪ್ರಶಾಂತ ತಾಣ. ಕೆಳದಿ ನಾಯಕರ ಆಳ್ವಿಕೆಯ ಸಾಕ್ಷಿ.', 'ತೀರ್ಥಹಳ್ಳಿಯಿಂದ ಸುಮಾರು 18 ಕಿ.ಮೀ ದೂರದಲ್ಲಿದೆ. ಬುಡದವರೆಗೆ ವಾಹನಗಳು ಹೋಗುತ್ತವೆ, ನಂತರ 2 ಕಿ.ಮೀ ಚಾರಣವಿದೆ.', 'ಕಡಿದಾದ ಕಲ್ಲಿನ ಹಾದಿ ಮತ್ತು ಎತ್ತರದ ಮೆಟ್ಟಿಲುಗಳಿವೆ.', 'human_reviewed'::public.translation_status) ON CONFLICT (destination_id, language_code) DO UPDATE SET name = EXCLUDED.name, summary = EXCLUDED.summary, description = EXCLUDED.description, how_to_reach = EXCLUDED.how_to_reach, accessibility_notes = EXCLUDED.accessibility_notes, translation_status = EXCLUDED.translation_status, updated_at = TIMEZONE('utc', NOW());
